// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 am) public {
        // Bound am to a reasonable range
        am = bound(am, 0, 100 ether);

        // First call: try Collect which will revert due to insufficient balance
        (bool success1, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", am));

        // Second call: Collect should not revert due to mutex being stuck
        // If the mutex is correctly released, this should succeed or revert only for other reasons
        (bool success2, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", am));

        // Rule: The second call must not revert because of a permanently locked mutex.
        // If the mutex is stuck, the second call would revert with "mutex did not release".
        // Since we can't catch internal revert reasons, we assert success2 must be possible.
        // Actually, the second call may revert for legitimate reasons (e.g., access control), but it must not revert because of the mutex.
        // A simpler rule: The second call must not revert due to the mutex; we check that if no other revert reason exists, success2 should be true.
        // For this test, we assert that the second call does not revert at all, because any revert after the first would indicate stuck mutex.
        // But this might be too strict if the second call also fails for valid reasons. 
        // Since we have no access to the lock, we can only observe revert boolean.
        // We choose: after a first revert call, a second call must succeed (or at least not revert for mutex).
        assertTrue(success2, "Second Collect must not revert, indicating mutex released");
    }
}

